      en: ["The oil field was officially discovered in 1953.", "It is ranked as the third-largest oil field in the world by reserves and area.", "Rumaila holds estimated recoverable reserves of approximately 17 billion barrels.", "Daily production currently averages between 1.4 and 1.5 million barrels of crude.", "Disputes over slant drilling at Rumaila were a key factor in the 1990 Gulf War.", "The field operations support more than 30,000 direct and indirect jobs in Iraq."],
